/**
 * Demo data. Idempotent: does nothing if the admin user already exists.
 * History is generated by an in-memory simulator so every ledger entry's balanceAfter is exactly consistent
 * with the final account balance (verified by the automated tests).
 */
import { eq } from "drizzle-orm";
import { buildSchedule, totalPayable } from "@/lib/loan-math";
import { hashSecret } from "../security";
import type { Database } from "./index";
import { accounts, bankSettings, fundRequests, ledgerEntries, loanInstallments, loanNotes, loans, notifications, transactionFlags, transactions, users } from "./schema";

export const DEMO = {
  password: "Password@123",
  pin: "2580",
  users: {
    admin: "admin@vaultline.test",
    staff: "staff@vaultline.test",
    staff2: "maya.staff@vaultline.test",
    customers: ["alice@vaultline.test", "bob@vaultline.test", "carol@vaultline.test", "david@vaultline.test", "emma@vaultline.test", "frank@vaultline.test"],
  },
};

// small deterministic PRNG so the seed is reproducible
function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const CUSTOMERS = [
  { name: "Alice Morgan", email: DEMO.users.customers[0], phone: "+1 555 0101", address: "12 Harbor Street, Boston, MA", dob: "1992-03-14", nid: "ID-480112", verified: true },
  { name: "Bob Henderson", email: DEMO.users.customers[1], phone: "+1 555 0102", address: "98 Pine Avenue, Austin, TX", dob: "1988-07-02", nid: "ID-771204", verified: true },
  { name: "Carol Nguyen", email: DEMO.users.customers[2], phone: "+1 555 0103", address: "7 Lakeview Road, Seattle, WA", dob: "1995-11-23", nid: "ID-330918", verified: true },
  { name: "David Okafor", email: DEMO.users.customers[3], phone: "+1 555 0104", address: "220 Market Street, Chicago, IL", dob: "1985-01-30", nid: "ID-559021", verified: true },
  { name: "Emma Schwartz", email: DEMO.users.customers[4], phone: "+1 555 0105", address: "5 Orchard Lane, Denver, CO", dob: "1999-09-09", nid: "ID-102233", verified: false },
  { name: "Frank Delgado", email: DEMO.users.customers[5], phone: "+1 555 0106", address: "41 Bay Road, Miami, FL", dob: "1979-05-18", nid: "ID-908817", verified: true },
];

const DESCRIPTIONS = ["Rent share", "Dinner split", "Birthday gift", "Groceries", "Freelance payment", "Utilities", "Books", "Concert tickets", "Loan to a friend", "Travel booking", "Monthly savings", "Furniture"];

type Sim = { id: string; number: string; balance: number };

export async function seedDatabase(db: Database, opts: { log?: (m: string) => void } = {}) {
  const log = opts.log ?? (() => {});
  const [existing] = await db.select({ id: users.id }).from(users).where(eq(users.email, DEMO.users.admin)).limit(1);
  if (existing) {
    log("• seed skipped (demo data already present)");
    return { skipped: true };
  }
  const rand = rng(20261121);
  const pick = <T>(a: readonly T[]) => a[Math.floor(rand() * a.length)];
  const between = (lo: number, hi: number) => lo + Math.floor(rand() * (hi - lo + 1));
  const pwHash = await hashSecret(DEMO.password);
  const pinHash = await hashSecret(DEMO.pin);
  const now = Date.now();
  const DAY = 86_400_000;

  await db.insert(bankSettings).values({ id: "global" }).onConflictDoNothing();

  /* ------------------------------------------------------------------ staff */
  const [admin] = await db.insert(users).values({ name: "Sarah Whitfield", email: DEMO.users.admin, passwordHash: pwHash, role: "ADMIN", createdAt: new Date(now - 400 * DAY) }).returning();
  const [staff] = await db.insert(users).values({ name: "Jordan Blake", email: DEMO.users.staff, passwordHash: pwHash, role: "STAFF", createdById: admin.id, createdAt: new Date(now - 380 * DAY) }).returning();
  await db.insert(users).values({ name: "Maya Patel", email: DEMO.users.staff2, passwordHash: pwHash, role: "STAFF", createdById: admin.id, createdAt: new Date(now - 300 * DAY) });

  /* --------------------------------------------------------------- customers */
  const custRows: (typeof users.$inferSelect)[] = [];
  for (let i = 0; i < CUSTOMERS.length; i++) {
    const c = CUSTOMERS[i];
    const created = new Date(now - (330 - i * 40) * DAY);
    const [u] = await db
      .insert(users)
      .values({
        customerNumber: `CUS-${String(100001 + i)}`, name: c.name, email: c.email, passwordHash: pwHash, pinHash, role: "CUSTOMER", phone: c.phone, address: c.address, dateOfBirth: c.dob, nationalId: c.nid,
        verified: c.verified, verifiedAt: c.verified ? created : null, verifiedById: c.verified ? staff.id : null, createdById: staff.id, createdAt: created,
      })
      .returning();
    custRows.push(u);
  }

  /* ---------------------------------------------------------------- accounts */
  const plan: { owner: number; type: "SAVINGS" | "CURRENT" | "BUSINESS"; nick?: string; opening: number; num: string }[] = [
    { owner: 0, type: "SAVINGS", nick: "Rainy day", opening: 1_800_000, num: "100000000101" },
    { owner: 0, type: "CURRENT", nick: "Everyday", opening: 650_000, num: "100000000102" },
    { owner: 1, type: "CURRENT", opening: 1_200_000, num: "100000000201" },
    { owner: 1, type: "BUSINESS", nick: "Henderson Studio", opening: 3_500_000, num: "100000000202" },
    { owner: 2, type: "SAVINGS", opening: 900_000, num: "100000000301" },
    { owner: 3, type: "CURRENT", opening: 2_200_000, num: "100000000401" },
    { owner: 4, type: "SAVINGS", opening: 300_000, num: "100000000501" },
    { owner: 5, type: "BUSINESS", nick: "Delgado Imports", opening: 5_000_000, num: "100000000601" },
  ];
  const sims: Sim[] = [];
  const accRows = [];
  for (const p of plan) {
    const [a] = await db.insert(accounts).values({ accountNumber: p.num, userId: custRows[p.owner].id, type: p.type, nickname: p.nick ?? null, balance: 0, createdById: staff.id, createdAt: new Date(now - 340 * DAY) }).returning();
    accRows.push(a);
    sims.push({ id: a.id, number: a.accountNumber, balance: 0 });
  }

  /* ----------------------------------------------- simulated 11-month history */
  // Every money movement (deposits, withdrawals, transfers, loan disbursements/repayments, approved requests)
  // goes through ONE chronological simulator so each ledger row's balanceAfter is exact.
  type Ev = { at: Date; kind: "DEPOSIT" | "WITHDRAWAL" | "TRANSFER" | "DISBURSE" | "REPAY"; from?: number; to?: number; amount: number; desc: string; id?: string; initiator?: string; loanKey?: number };
  const events: Ev[] = [];
  plan.forEach((p, i) => events.push({ at: new Date(now - 335 * DAY + i * 3_600_000), kind: "DEPOSIT", to: i, amount: p.opening, desc: "Opening deposit", initiator: staff.id }));
  for (let d = 330; d >= 1; d--) {
    const perDay = rand() < 0.55 ? 1 + Math.floor(rand() * 2) : 0;
    for (let k = 0; k < perDay; k++) {
      const at = new Date(now - d * DAY + between(8, 20) * 3_600_000 + between(0, 59) * 60_000);
      const roll = rand();
      if (roll < 0.28) events.push({ at, kind: "DEPOSIT", to: between(0, plan.length - 1), amount: between(20, 400) * 1000 + between(0, 99) * 10, desc: pick(["Salary credit", "Cash deposit", "Cheque deposit", "Client payment"]) });
      else if (roll < 0.5) events.push({ at, kind: "WITHDRAWAL", from: between(0, plan.length - 1), amount: between(5, 120) * 1000, desc: pick(["ATM withdrawal", "Branch withdrawal", "Cash for expenses"]) });
      else {
        const from = between(0, plan.length - 1);
        let to = between(0, plan.length - 1);
        if (to === from) to = (to + 1) % plan.length;
        events.push({ at, kind: "TRANSFER", from, to, amount: between(5, 250) * 1000, desc: pick(DESCRIPTIONS) });
      }
    }
  }

  /* loans: decide ids/schedules first so their disbursement + repayments join the same timeline */
  const loanSpecs = [
    { owner: 0, acc: 0, type: "PERSONAL" as const, amount: 600_000, months: 12, bps: 1200, income: 520_000, emp: "EMPLOYED" as const, status: "ACTIVE" as const, paid: 4, ago: 150, desc: "Home renovation and furniture" },
    { owner: 1, acc: 3, type: "BUSINESS" as const, amount: 2_500_000, months: 24, bps: 1100, income: 1_100_000, emp: "BUSINESS_OWNER" as const, status: "ACTIVE" as const, paid: 7, ago: 230, desc: "New studio equipment" },
    { owner: 2, acc: 4, type: "EDUCATION" as const, amount: 1_800_000, months: 36, bps: 600, income: 380_000, emp: "STUDENT" as const, status: "PENDING" as const, paid: 0, ago: 2, desc: "Master's degree tuition fees" },
    { owner: 3, acc: 5, type: "AUTO" as const, amount: 2_200_000, months: 48, bps: 1000, income: 700_000, emp: "EMPLOYED" as const, status: "UNDER_REVIEW" as const, paid: 0, ago: 6, desc: "Purchase of a family car" },
    { owner: 5, acc: 7, type: "BUSINESS" as const, amount: 4_000_000, months: 18, bps: 1100, income: 1_500_000, emp: "SELF_EMPLOYED" as const, status: "REJECTED" as const, paid: 0, ago: 40, desc: "Expansion of the import warehouse" },
    { owner: 0, acc: 1, type: "PERSONAL" as const, amount: 300_000, months: 6, bps: 1200, income: 520_000, emp: "EMPLOYED" as const, status: "COMPLETED" as const, paid: 6, ago: 260, desc: "Medical expenses" },
  ];
  const loanPlans = loanSpecs.map((spec, i) => {
    const created = new Date(now - spec.ago * DAY);
    const decided = ["ACTIVE", "COMPLETED", "REJECTED"].includes(spec.status) ? new Date(created.getTime() + 3 * DAY) : null;
    const active = spec.status === "ACTIVE" || spec.status === "COMPLETED";
    const schedule = buildSchedule(spec.amount, spec.bps, spec.months, new Date(created.getTime() + 3 * DAY));
    const loanNumber = `LN-${created.toISOString().slice(0, 10).replace(/-/g, "")}-D${String(i + 1).padStart(4, "0")}`;
    const disbId = crypto.randomUUID();
    const repayIds = schedule.map(() => crypto.randomUUID());
    if (active) {
      events.push({ at: decided!, kind: "DISBURSE", to: spec.acc, amount: spec.amount, desc: `Disbursement of loan ${loanNumber}`, id: disbId, initiator: admin.id });
      for (const row of schedule.filter((r) => r.number <= spec.paid))
        events.push({ at: new Date(`${row.dueDate}T10:00:00Z`), kind: "REPAY", from: spec.acc, amount: row.amount, desc: `Loan ${loanNumber} - instalment ${row.number}/${spec.months}`, id: repayIds[row.number - 1], initiator: custRows[spec.owner].id });
    }
    return { spec, created, decided, active, schedule, loanNumber, disbId, repayIds, loanId: crypto.randomUUID() };
  });

  // an approved historic deposit request participates in the timeline too
  const histDepositTxn = crypto.randomUUID();
  const histAt = new Date(now - 12 * DAY);
  events.push({ at: histAt, kind: "DEPOSIT", to: 1, amount: 100_000, desc: "Historic request", id: histDepositTxn, initiator: custRows[plan[1].owner].id });

  events.sort((a, b) => a.at.getTime() - b.at.getTime());

  const FEE = 50;
  let seq = 0;
  const ref = (at: Date) => `TXN-${at.toISOString().slice(0, 10).replace(/-/g, "")}-S${String(++seq).padStart(7, "0")}`;
  const txnRows: (typeof transactions.$inferInsert)[] = [];
  const ledgerRows: (typeof ledgerEntries.$inferInsert)[] = [];

  for (const e of events) {
    const id = e.id ?? crypto.randomUUID();
    const done = { status: "COMPLETED" as const, createdAt: e.at, completedAt: e.at };
    if (e.kind === "DEPOSIT" || e.kind === "DISBURSE") {
      const t = sims[e.to!];
      t.balance += e.amount;
      txnRows.push({ id, txnId: ref(e.at), type: e.kind === "DEPOSIT" ? "DEPOSIT" : "LOAN_DISBURSEMENT", receiverAccountId: t.id, amount: e.amount, description: e.desc, initiatedById: e.initiator ?? staff.id, ...done });
      ledgerRows.push({ transactionId: id, accountId: t.id, direction: "CREDIT", amount: e.amount, balanceAfter: t.balance, createdAt: e.at });
    } else if (e.kind === "WITHDRAWAL" || e.kind === "REPAY") {
      const f = sims[e.from!];
      if (e.kind === "WITHDRAWAL" && f.balance - e.amount < 50_000) continue;
      f.balance -= e.amount;
      txnRows.push({ id, txnId: ref(e.at), type: e.kind === "WITHDRAWAL" ? "WITHDRAWAL" : "LOAN_REPAYMENT", senderAccountId: f.id, amount: e.amount, description: e.desc, initiatedById: e.initiator ?? custRows[plan[e.from!].owner].id, ...done });
      ledgerRows.push({ transactionId: id, accountId: f.id, direction: "DEBIT", amount: e.amount, balanceAfter: f.balance, createdAt: e.at });
    } else {
      const f = sims[e.from!], t = sims[e.to!];
      const fee = plan[e.from!].owner === plan[e.to!].owner ? 0 : FEE;
      if (f.balance - e.amount - fee < 50_000) continue;
      f.balance -= e.amount + fee;
      t.balance += e.amount;
      txnRows.push({ id, txnId: ref(e.at), type: "TRANSFER", senderAccountId: f.id, receiverAccountId: t.id, amount: e.amount, fee, description: e.desc, initiatedById: custRows[plan[e.from!].owner].id, ...done });
      ledgerRows.push({ transactionId: id, accountId: f.id, direction: "DEBIT", amount: e.amount + fee, balanceAfter: f.balance, createdAt: e.at });
      ledgerRows.push({ transactionId: id, accountId: t.id, direction: "CREDIT", amount: e.amount, balanceAfter: t.balance, createdAt: e.at });
    }
  }
  const chunk = <T>(arr: T[], n = 200) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
  for (const c of chunk(txnRows)) await db.insert(transactions).values(c);
  for (const c of chunk(ledgerRows, 400)) await db.insert(ledgerEntries).values(c);
  for (const s of sims) await db.update(accounts).set({ balance: s.balance }).where(eq(accounts.id, s.id));

  /* --------------------------------------------------------------------- loans */
  for (const lp of loanPlans) {
    const { spec, created, decided, active, schedule } = lp;
    await db.insert(loans).values({
      id: lp.loanId, loanNumber: lp.loanNumber, userId: custRows[spec.owner].id, accountId: accRows[spec.acc].id, type: spec.type,
      requestedAmount: spec.amount, approvedAmount: active ? spec.amount : null, durationMonths: spec.months, interestBps: spec.bps, monthlyIncome: spec.income, employmentStatus: spec.emp, description: spec.desc,
      status: spec.status, emi: active ? schedule[0].amount : null, totalPayable: active ? totalPayable(schedule) : null,
      forwardedById: spec.status !== "PENDING" ? staff.id : null, forwardedAt: spec.status !== "PENDING" ? new Date(created.getTime() + DAY) : null,
      decidedById: decided ? admin.id : null, decidedAt: decided, decisionNote: spec.status === "REJECTED" ? "Requested amount is too high relative to documented income." : null,
      disbursedAt: active ? decided : null, disbursementTxnId: active ? lp.disbId : null, createdAt: created, updatedAt: created,
    });
    if (spec.status !== "PENDING") await db.insert(loanNotes).values({ loanId: lp.loanId, authorId: staff.id, body: "Documents checked. Income statement and ID match the application.", createdAt: new Date(created.getTime() + DAY) });
    if (active)
      await db.insert(loanInstallments).values(
        schedule.map((r) => {
          const paid = r.number <= spec.paid;
          return { loanId: lp.loanId, number: r.number, dueDate: r.dueDate, principal: r.principal, interest: r.interest, amount: r.amount, status: paid ? ("PAID" as const) : ("PENDING" as const), paidAt: paid ? new Date(`${r.dueDate}T10:00:00Z`) : null, transactionId: paid ? lp.repayIds[r.number - 1] : null };
        }),
      );
  }

  /* ----------------------------------------- pending deposit / withdrawal requests */
  const pendingReqs: { acc: number; type: "DEPOSIT" | "WITHDRAWAL"; amount: number; desc: string; ago: number }[] = [
    { acc: 0, type: "DEPOSIT", amount: 250_000, desc: "Cash deposit at branch", ago: 0.2 },
    { acc: 2, type: "WITHDRAWAL", amount: 80_000, desc: "Cash needed for rent", ago: 0.5 },
    { acc: 4, type: "DEPOSIT", amount: 120_000, desc: "Cheque deposit", ago: 1 },
    { acc: 5, type: "WITHDRAWAL", amount: 150_000, desc: "Car down payment", ago: 1.5 },
    { acc: 6, type: "DEPOSIT", amount: 60_000, desc: "Scholarship payout", ago: 2 },
  ];
  let reqSeq = 1;
  const reqNo = (at: Date, tag: string) => `REQ-${at.toISOString().slice(0, 10).replace(/-/g, "")}-${tag}${String(reqSeq++).padStart(4, "0")}`;
  for (const r of pendingReqs) {
    const at = new Date(now - r.ago * DAY);
    const tId = crypto.randomUUID();
    await db.insert(transactions).values({
      id: tId, txnId: ref(at), type: r.type, status: "PENDING", senderAccountId: r.type === "WITHDRAWAL" ? accRows[r.acc].id : null, receiverAccountId: r.type === "DEPOSIT" ? accRows[r.acc].id : null,
      amount: r.amount, description: r.desc, initiatedById: custRows[plan[r.acc].owner].id, createdAt: at,
    });
    await db.insert(fundRequests).values({ requestNumber: reqNo(at, "D"), type: r.type, accountId: accRows[r.acc].id, userId: custRows[plan[r.acc].owner].id, amount: r.amount, description: r.desc, transactionId: tId, createdAt: at });
  }
  // reviewed history: one approved (its money is already part of the timeline above) and one rejected
  await db.insert(fundRequests).values({
    requestNumber: reqNo(histAt, "H"), type: "DEPOSIT", accountId: accRows[1].id, userId: custRows[plan[1].owner].id, amount: 100_000, description: "Historic request",
    status: "APPROVED", transactionId: histDepositTxn, reviewedById: staff.id, reviewedAt: new Date(histAt.getTime() + 3_600_000), reviewNote: "Verified at branch", createdAt: histAt,
  });
  const rejAt = new Date(now - 20 * DAY);
  const rejTxn = crypto.randomUUID();
  await db.insert(transactions).values({ id: rejTxn, txnId: ref(rejAt), type: "WITHDRAWAL", status: "FAILED", failureReason: "Exceeds the single transaction limit", senderAccountId: accRows[3].id, amount: 9_000_000, description: "Historic request", initiatedById: custRows[plan[3].owner].id, createdAt: rejAt });
  await db.insert(fundRequests).values({
    requestNumber: reqNo(rejAt, "H"), type: "WITHDRAWAL", accountId: accRows[3].id, userId: custRows[plan[3].owner].id, amount: 9_000_000, description: "Historic request",
    status: "REJECTED", transactionId: rejTxn, reviewedById: staff.id, reviewedAt: new Date(rejAt.getTime() + 3_600_000), reviewNote: "Exceeds the single transaction limit", createdAt: rejAt,
  });

  /* ------------------------------------------------------------ suspicious flags */
  const stored = await db.select({ id: transactions.id, txnId: transactions.txnId, amount: transactions.amount }).from(transactions).where(eq(transactions.type, "TRANSFER"));
  const biggest = stored.sort((a, b) => b.amount - a.amount).slice(0, 3);
  const reasons = ["Large share of the balance sent to a first-time recipient", "Amount sits just below the single-transaction limit", "Customer reported not recognising this payment"];
  for (let i = 0; i < biggest.length; i++)
    await db.insert(transactionFlags).values({ transactionId: biggest[i].id, source: i === 2 ? "STAFF" : "SYSTEM", reason: reasons[i], raisedById: i === 2 ? staff.id : null, status: i === 0 ? "DISMISSED" : "OPEN", resolvedById: i === 0 ? admin.id : null, resolvedAt: i === 0 ? new Date() : null, resolutionNote: i === 0 ? "Verified with the customer by phone." : null });

  /* ---------------------------------------------------------------- notifications */
  for (const [i, u] of custRows.entries())
    await db.insert(notifications).values({ userId: u.id, type: "WELCOME", title: "Welcome to Vaultline", message: "Your profile is ready. Explore your dashboard, send money and track your loans.", link: "/customer", read: i % 2 === 0, createdAt: new Date(now - 3 * DAY) });
  await db.insert(notifications).values({ userId: admin.id, type: "SUSPICIOUS_ACTIVITY", title: "Suspicious transactions waiting", message: "2 flagged transactions need your review.", link: "/admin/flags" });

  log(`✔ seeded: 1 admin, 2 staff, ${custRows.length} customers, ${accRows.length} accounts, ${txnRows.length}+ transactions, ${loanSpecs.length} loans`);
  log(`  admin    ${DEMO.users.admin}   / ${DEMO.password}`);
  log(`  staff    ${DEMO.users.staff}   / ${DEMO.password}`);
  log(`  customer ${DEMO.users.customers[0]}   / ${DEMO.password}  (PIN ${DEMO.pin})`);
  return { skipped: false };
}
